import type { MachineData, MachinePoint } from "../../src/types.js";

function pt(
  machine: string,
  value: number,
  ts: string,
): MachinePoint {
  return {
    timestamp: new Date(ts).getTime() / 1000,
    value,
    revision: "deadbeef1234",
    push_id: 1,
    job_id: 1,
    machine_name: machine,
  };
}

